class Solution {
    public int closestValue(TreeNode root, double target) {
        int closest = root.val;
        TreeNode curr = root;
        while (curr != null) {
            double diff = Math.abs(curr.val - target);
            double bestDiff = Math.abs(closest - target);
            if (diff < bestDiff || (diff == bestDiff && curr.val < closest)) {
                closest = curr.val;
            }
            if (target < curr.val) {
                curr = curr.left;
            } else {
                curr = curr.right;
            }
        }
        return closest;
    }
}

